window.LEARNING_CONTENT={};
(() => {
const specific={
'cva-value':[['Why can CVA change before a default occurs?','It is a current valuation of possible future loss, so changing market spreads or expected exposure changes its value today.'],['Does a CVA of £1m mean a £1m default loss is certain?','No. It is an expected discounted loss across possible default times and exposure states.'],['Why take positive exposure?','A counterparty default threatens claims owed to the firm, rather than amounts the firm itself owes.'],['Can own-credit deterioration reduce this regulatory CVA?','No. Regulatory CVA is unilateral and assumes the firm is free of default risk.'],['Why is CVA value different from capital?','CVA is a valuation adjustment; SA-CVA capital covers sensitivity of that adjustment to market movements.']],
'netting':[['Can two offsetting trades always be netted?','No. Economic offsets require a recognised enforceable netting arrangement before exposure can be combined.'],['Why does taking positive parts first change the result?','A payable is discarded separately, so it cannot offset a receivable after the positive-part operation.'],['Does negative net value create negative unilateral exposure?','No. The positive-part operation floors this exposure at zero.'],['Does netting today guarantee zero future exposure?','No. Trade values change differently across future market paths.'],['Can one counterparty have multiple netting sets?','Yes. The legal arrangements determine which transactions can be combined.']],
'collateral':[['Why can daily margin leave exposure?','Market values can change during the margin period before close-out or replacement.'],['What happens when the threshold rises?','Less collateral is assumed collected, leaving more of the current receivable unsecured.'],['Does a longer margin period create certainty of loss?','No. It widens the range of potential market moves and may increase expected positive exposure.'],['Why does a zero-mean shock still create positive exposure?','Negative outcomes are floored at zero while positive outcomes remain.'],['Is this normal-shock model prescribed by the PRA?','No. The MPOR minimum is prescribed; this distribution is a transparent teaching assumption.']],
'wrong-way':[['Why can averages conceal wrong-way risk?','Separate averages discard whether high exposure and high default likelihood occur together.'],['What changes when alignment reverses?','The same marginal averages can produce a different joint expected loss.'],['Is positive alignment always wrong-way risk here?','Only if the state with higher default probability also has higher exposure.'],['Can diversification remove every dependence?','No. Shared economic drivers can connect exposure and counterparty credit quality.'],['Is the alignment slider a regulatory correlation?','No. It is a synthetic two-state dependence parameter.']],
'credit-curve':[['Why use a term structure?','Default likelihood and exposure vary by horizon, so timing affects expected loss.'],['Are market-implied probabilities forecasts?','They are calibrated valuation inputs and need not equal real-world default frequencies.'],['Why must LGD and the curve be consistent?','The LGD used to extract probabilities from spreads affects the probabilities obtained.'],['What makes a proxy credible?','Relevant credit quality, industry and region, with documented justification and controls.'],['Can historical defaults alone supply missing spreads?','The PRA rule does not allow resulting spreads to rely solely on historical default probabilities.']],
'sensitivities':[['Why divide the value change by the bump?','This normalises the change to a unit sensitivity before applying regulatory weights.'],['Does a relative volatility bump add one percentage point?','No. A one-percent relative shift takes twenty-percent volatility to twenty-point-two percent.'],['Can linear derivatives generate CVA vega?','Yes. Volatility can change future positive exposure even without explicit option payoffs.'],['Why revalue instead of guessing sensitivity?','Revaluation captures the model’s dependence on the shifted risk factor.'],['Is the displayed sensitivity the bump profit or loss?','No. It is the bump value change divided by the specified shift size.']],
'hedging':[['Why subtract hedge sensitivity?','CVA is loss-positive, while a positive hedge value change offsets that valuation loss.'],['Why does a perfect match leave capital?','The prescribed hedge-disallowance term remains inside the square root.'],['Can more hedge increase the charge?','Yes. Overhedging reverses net sensitivity and also increases the hedge term.'],['Does economic usefulness establish eligibility?','No. The hedge must satisfy the regulatory eligibility and allocation conditions.'],['Can a credit hedge be counted in two delta classes?','No. It must be assigned wholly to counterparty or reference credit-spread delta.']],
'cva-total':[['Why are there eleven components?','There are six delta classes and five vega classes; counterparty credit spreads have no separate vega class.'],['Can equity cancel an FX capital charge?','No. Class charges are summed without cross-class diversification.'],['Should curvature be added here?','No. SA-CVA does not use FRTB’s curvature charge.'],['Should the reduced BA-CVA scalar be applied?','No. The SA-CVA multiplier is one, not the reduced BA-CVA scalar.'],['Does this total include counterparty default capital?','No. CCR default capital is a separate requirement.']],
'cva-governance':[['Can readiness replace permission?','No. PRA permission is required for the intended SA-CVA scope.'],['Why require independent validation?','Independent challenge helps reveal model weaknesses and assumptions that model owners may overlook.'],['Are all securities financing transactions in scope?','The fair-value and CVA-risk materiality conditions determine inclusion.'],['Why retain an audit trail?','Inputs, decisions and calculations must be traceable and reproducible.'],['Is transitional relief a blanket discount?','No. Chapter 7 has specified eligibility and calculation conditions.']]
};
for(const l of CVA_LESSONS){
 const p=window.CVA_CLASSES.find(p=>p.id===l.id);
 const qs=specific[l.id]||(p?[
 ['What does a sensitivity represent in '+p.name+'?',p.scope],
 ['How are offsets recognised within '+p.name+'?',p.detail],
 ['Why does a matching hedge still leave '+p.name+' capital?','The prescribed 0.01 times squared weighted hedge term remains under the square root, even when net sensitivity is zero.'],
 ['Can this '+p.name+' lab represent every possible portfolio?','No. It uses the explicitly described representative buckets and zero sensitivity for all omitted factors.'],
 ['What changes when '+p.name+' capital enters the portfolio total?','Its delta and, where applicable, vega charge are added to other class charges without further cross-class diversification.']
 ]:[]);
 window.LEARNING_CONTENT[l.id]={intuition:[l.simple,l.scope],questions:[...qs,
 ['In “'+l.name+'”, which assumption would you challenge first?',l.scope],
 ['How would you explain “'+l.name+'” to a colleague without using its equation?',l.simple],
 ['What experiment would help you understand “'+l.name+'”?',l.challenge+' Change one control at a time and compare the explanation and calculation table.'],
 ['Where would you check the regulatory treatment of “'+l.name+'”?','Use the linked PRA provisions below this applet. Distinguish prescribed rules from the explicitly labelled synthetic assumptions.'],
 ['What should you avoid concluding from “'+l.name+'”?','A result for a synthetic example does not establish a firm’s regulatory capital or compliance. '+l.key]
 ]};
}
})();
